script:
# Check for loss before submitting sales invoice
if flt(doc.custom_loss_) > 0 and doc.docstatus == 1:
    # Import the check function
    from invoice_profitability.invoice_profitability.utils import check_loss_sale

    result = check_loss_sale(doc.name)

    if result.get('has_loss'):
        # Check if already confirmed
        if not doc.custom_loss_confirmed:
            frappe.throw(
                "This sale is at a loss of {0}% (Loss Amount: {1}). Please confirm the loss sale before submitting.".format(
                    flt(doc.custom_loss_, 2),
                    flt(doc.custom_total_average_cost - doc.custom_total_incoming_cost, 2)
                ),
                title="Loss Sale Warning"
            )
